41→test("an asset whose visibility could not be read is reported, not planned", () => {
42→  const plan = planVisibility({ mode: "apply", baseline, current: { [WRONG]: null, [RIGHT]: "team" } });
43→  assert.deepEqual(plan.unreadable.sort(), [PEND, WRONG].sort());
44→  assert.deepEqual(plan.changes, []);
45→  assert.match(renderPlan(plan), /could not be read — NOT planned/);
46→});
47→
48→test("an asset in the baseline with no decision keeps the baseline and is listed as undecided", () => {
49→  const b = { assets: { [RIGHT]: { baseline_visibility: "team" } }, decisions: [] };
50→  const plan = planVisibility({ mode: "apply", baseline: b, current: { [RIGHT]: HIDDEN } });
51→  assert.deepEqual(plan.undecided, [RIGHT]);
52→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.to]), [[RIGHT, "team"]]);
53→});
54→
55→test("unknown mode throws", () => {
56→  assert.throws(() => planVisibility({ mode: "nuke", baseline, current: {} }), /mode must be/);
57→});
58→
59→test("render lists changes and unchanged, or says nothing to change", () => {
60→  const plan = planVisibility({ mode: "reset", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" } });
61→  assert.match(renderPlan(plan), /nothing to change/);
62→});
63→
64→test("hide mode: named assets private, everything else at baseline, decisions ignored", () => {
65→  const plan = planVisibility({ mode: "hide", baseline, current: { [WRONG]: "team", [RIGHT]: "team", [PEND]: "team" }, hide: [RIGHT] });
66→  assert.deepEqual(plan.changes.map((c) => [c.asset_id, c.from, c.to]), [[RIGHT, "team", HIDDEN]]);
67→  assert.match(plan.changes[0].because, /leave-one-out: hidden/);
68→  // the rejected asset is NOT hidden in hide mode — decisions are not applied
69→  assert.ok(plan.unchanged.find((u) => u.asset_id === WRONG));
70→});
