 66→export function buildBaseline({ runs, snapshot, visibility = null, tokensByAsset = {}, decoys = [], now }) {
 67→  const frozenAt = now ?? new Date().toISOString().replace(/\.\d{3}Z$/, "Z");
 68→  const seen = new Map();
 69→  const sourceRuns = [];
 70→  for (const r of runs) {
 71→    const ids = [];
 72→    for (const e of r.events) {
 73→      if (!seen.has(e.event_id)) { seen.set(e.event_id, e); ids.push(e.event_id); }
 74→    }
 75→    sourceRuns.push({ run_id: r.run_id, label: r.label, verdict: r.verdict, started_at: r.started_at, outcome_source: r.outcome_source, event_ids: ids });
 76→  }
 77→  const events = [...seen.values()];
 78→  const decisions = decide({ events, snapshot, decoys, now: frozenAt, tokensByAsset });
 79→
 80→  const assets = {};
 81→  for (const a of snapshot.assets ?? []) {
 82→    const vis = visibility?.[a.asset_id] ?? null;
 83→    assets[a.asset_id] = {
 84→      name: a.name ?? null,
 85→      version: a.version ?? null,
 86→      producer_user_id: a.producer_user_id ?? null,
 87→      producer_agent_id: a.producer_agent_id ?? null,
 88→      // The pool as entered: every scenario asset is team-visible (enter-pool.sh
 89→      // checks it). If the live value was supplied it is recorded as read; if
 90→      // not, "team" is the contract and the source says it was not read.
 91→      baseline_visibility: vis ?? "team",
 92→      visibility_source: vis ? "read from /v3/meta/asset/get at freeze time" : "enter-pool.sh contract (not read at freeze time)",
 93→    };
 94→  }
 95→
 96→  return {
 97→    schema_version: "gate-baseline-v1",
 98→    frozen_at: frozenAt,
 99→    pool_snapshot_at: snapshot.pool_snapshot_at ?? null,
100→    team_id: snapshot.team_id ?? null,
101→    source_runs: sourceRuns,
102→    event_count: events.length,
103→    by_state: events.reduce((acc, e) => { acc[e.state] = (acc[e.state] ?? 0) + 1; return acc; }, {}),
104→    assets,
105→    decisions,
106→    events,
107→    note: "Every comparison run resets to this baseline before it starts (apply.sh --reset / --apply). "
108→        + "Runs listed in source_runs are the evidence base and are not part of the comparison.",
109→  };
110→}
