 1→import { test } from "node:test";
 2→import assert from "node:assert/strict";
 3→import { createServer } from "node:net";
 4→import { probe, probeAll, targetsOf } from "./probe-reachability.mjs";
 5→
 6→function listen() {
 7→  return new Promise((resolve) => {
 8→    const server = createServer((s) => s.end());
 9→    server.listen(0, "127.0.0.1", () => resolve({ server, port: server.address().port }));
10→  });
11→}
12→
13→test("a listening port is reachable; a closed port is 'could not connect'", async () => {
14→  const { server, port } = await listen();
15→  try {
16→    const ok = await probe("127.0.0.1", port, { timeoutMs: 2000 });
17→    assert.equal(ok.ok, true);
18→    assert.equal(ok.why, "tcp connect ok");
19→  } finally {
20→    server.close();
21→  }
22→  const closed = await probe("127.0.0.1", port, { timeoutMs: 2000 });
23→  assert.equal(closed.ok, false);
24→  assert.equal(closed.why, "could not connect");
25→});
26→
27→test("a non-routable address times out within the budget", async () => {
28→  const r = await probe("10.255.255.1", 9, { timeoutMs: 800 });
29→  assert.equal(r.ok, false);
30→  assert.ok(["timed out", "could not connect"].includes(r.why) || r.why.startsWith("error "), r.why);
31→  assert.ok(r.elapsed_ms < 5000);
32→});
33→
34→test("targetsOf dedupes host:port pairs from the verdict's attempts", () => {
35→  const v = { attempts: [{ host: "a", port: "1" }, { host: "a", port: "1" }, { host: "b", port: "2" }, { host: null, port: "3" }] };
36→  assert.deepEqual(targetsOf(v), ["a:1", "b:2"]);
37→});
38→
39→test("probeAll records source and time per target", async () => {
40→  const { server, port } = await listen();
41→  try {
42→    const rec = await probeAll([`127.0.0.1:${port}`], { timeoutMs: 2000, source: "unit test" });
43→    const t = rec.targets[`127.0.0.1:${port}`];
44→    assert.equal(t.ok, true);
45→    assert.equal(t.source, "unit test");
46→    assert.match(t.checked_at, /^\d{4}-\d{2}-\d{2}T/);
47→  } finally {
48→    server.close();
49→  }
50→});
